COMMENT ON COLUMN finances.learner_financial_plan.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN finances.learner_financial_plan.person_identifier IS 'A unique number or alphanumeric code assigned to a person';
COMMENT ON COLUMN finances.learner_financial_plan.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN finances.learner_financial_plan.name IS 'A name for the record';
COMMENT ON COLUMN finances.learner_financial_plan.time_period IS 'Timeframe of the budget or financial plan (e.g. monthly, yearly)';
COMMENT ON COLUMN finances.learner_financial_plan.start_date IS 'Start date of the budget or financial plan time period';
COMMENT ON COLUMN finances.learner_financial_plan.end_date IS 'End date of the budget or financial plan time period';
COMMENT ON COLUMN finances.learner_financial_plan.projected_income_total IS 'Total expected income for the budget for financial plan time period (calculated)';
COMMENT ON COLUMN finances.learner_financial_plan.projected_expenses_total IS 'Total expected expenses for the budget or financial plan time period (calculated)';
COMMENT ON COLUMN finances.learner_financial_plan.projected_net_balance IS 'Projected balance after income and expenses for the budget or financial plan time period';
COMMENT ON COLUMN finances.learner_financial_plan.actual_income_total IS 'Total actual income for the budget or financial plan time period';
COMMENT ON COLUMN finances.learner_financial_plan.actual_expenses_total IS 'Total actual expenses for the budget or financial plan time period';
COMMENT ON COLUMN finances.learner_financial_plan.actual_net_balance IS 'Actual balance at the end of the budget or financial plan time period';
COMMENT ON COLUMN finances.learner_financial_plan.date_issued IS 'The month, day, and year that the College Financing Plan was created to notify the prospective student about their financial aid package';
COMMENT ON COLUMN finances.learner_financial_plan.type IS 'Type of financial plan (organization provided plan, learner provided plan, actual expenditures)';
COMMENT ON COLUMN finances.learner_financial_plan.status IS 'Status of a financial plan (active, inactive)';
COMMENT ON COLUMN finances.learner_financial_plan.estimated_terms_remaining IS 'Number of terms the learner estimates will be required for completion';
COMMENT ON COLUMN finances.learner_financial_plan.estimated_term_cost IS 'Total cost a learner estimates for a term of enrollment';
COMMENT ON COLUMN finances.learner_financial_plan.financial_plan_history IS 'Indicates whether this plan is for a current, previous, or future school year';
COMMENT ON COLUMN finances.learner_financial_plan.tuition_and_fees IS 'Tuition and Fees; This information is generated by the institution itself and should provide a clear understanding of the costs associated with one year of enrollment at the institution for the named student. (dollars)';
COMMENT ON COLUMN finances.learner_financial_plan.housing_and_food_on_campus IS 'Housing and food on campus; This information is generated by the institution itself and should provide a clear understanding of the costs associated with one year of enrollment at the institution for the named student. (dollars)';
COMMENT ON COLUMN finances.learner_financial_plan.housing_and_food_off_campus IS 'Housing and food off campus; This information is generated by the institution itself and should provide a clear understanding of the costs associated with one year of enrollment at the institution for the named student. (dollars)';
COMMENT ON COLUMN finances.learner_financial_plan.boarding_cost IS 'Boarding costs (food only); This information is generated by the institution itself and should provide a clear undestanding of the costs associated with one year of enrollment at the institution for the learner (dollars)';
COMMENT ON COLUMN finances.learner_financial_plan.books_and_supplies IS 'Books and supplies; This information is generated by the institution itself and should provide a clear understanding of the costs associated with one year of enrollment at the institution for the named student. (dollars)';
COMMENT ON COLUMN finances.learner_financial_plan.transportation IS 'Transportation; This information is generated by the institution itself and should provide a clear understanding of the costs associated with one year of enrollment at the institution for the named student. (dollars)';
COMMENT ON COLUMN finances.learner_financial_plan.other_education_costs IS 'Other education costs; This information is generated by the institution itself and should provide a clear understanding of the costs associated with one year of enrollment at the institution for the named student. (dollars)';
COMMENT ON COLUMN finances.learner_financial_plan.estimated_costs_on_campus IS 'Total estimated costs if the student lives on campus; This information is generated by the institution itself and should provide a clear understanding of the costs associated with one year of enrollment at the institution for the named student. (dollars)';
COMMENT ON COLUMN finances.learner_financial_plan.estimated_costs_off_campus IS 'Total estimated costs if the student lives off campus; This information is generated by the institution itself and should provide a clear understanding of the costs associated with one year of enrollment at the institution for the named student. (dollars)';
COMMENT ON COLUMN finances.learner_financial_plan.student_aid_index_based_on_fafsa IS 'Student Aid Index Based on FAFSA; At most institutions, the expected family contribution is based on the FAFSA results; however, if an institutional methodology is used, that result may be provided. (dollars)';
COMMENT ON COLUMN finances.learner_financial_plan.student_aid_index_based_on_institutional_method IS 'Student Aid Index Based on Institutional Method; At most institutions, the expected family contribution is based on the FAFSA results; however, if an institutional methodology is used, that result may be provided. (dollars)';
COMMENT ON COLUMN finances.learner_financial_plan.parent_contribution_amount IS 'Tuition and Fees; This information is generated by the institution itself and should provide a clear understanding of the costs associated with one year of enrollment at the institution for the named student';
COMMENT ON COLUMN finances.learner_financial_plan.net_price IS 'This number reflects the net cost of attendance for the named student after grants and scholarships are taken into account';
COMMENT ON COLUMN finances.learner_financial_plan.tuition_payment_plan_indicator IS 'Tuition payment plan offered by the institution';
COMMENT ON COLUMN finances.learner_financial_plan.source_system_key_value IS 'Unique identifier of this record in the source system';
COMMENT ON COLUMN finances.learner_financial_plan.source_system_created_date IS 'Date the record was created in the source system';
COMMENT ON COLUMN finances.learner_financial_plan.source_system_updated_date IS 'Date the record was last updated in the source system';
COMMENT ON COLUMN finances.learner_financial_plan.source_system_deleted_date IS 'Date the record was deleted from the source system';
COMMENT ON COLUMN finances.learner_financial_plan.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN finances.learner_financial_plan.created_date IS 'Date and time record was created';
COMMENT ON COLUMN finances.learner_financial_plan.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN finances.learner_financial_plan.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN finances.learner_financial_plan.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN finances.learner_financial_plan.deleted_date IS 'Date and time record was deleted';

-- LearnerFinancialPlanExpense
-- A table for a learner's budget or financial plan expenses.
