COMMENT ON COLUMN finances.learner_financial_plan_expense.paid_by_financial_aid_award_identifier IS 'Unique identifier for a financial aid award item';
COMMENT ON COLUMN finances.learner_financial_plan_expense.expense_category IS 'Type of expense (e.g. rent, food, transportation, entertainment)';
COMMENT ON COLUMN finances.learner_financial_plan_expense.expense_amount IS 'Amount of the expense (dollars)';
