-- LearnerThirdPartyBenefit
-- A table that stores learner-associated third-party education benefit, sponsorship, tuition
-- reimbursement, employer reimbursement, voucher, or outside funding-support facts. This table
-- captures benefit eligibility or sponsorship context without becoming the authoritative
-- financial-aid award, billing, payment, or ledger transaction table.
CREATE TABLE finances.learner_third_party_benefit (
    tenant_identifier                                UUID NOT NULL,
    person_identifier                                TEXT NOT NULL,
    sequence_number                                  TEXT NOT NULL,
    benefit_type_identifier                          TEXT,
    benefit_source_type_identifier                   TEXT,
    benefit_status_identifier                        TEXT,
    benefit_available_indicator                      BOOLEAN DEFAULT FALSE,
    benefit_provider_name                            TEXT,
    employer_name                                    TEXT,
    related_employment_sequence_number               INTEGER,
    benefit_amount                                   NUMERIC,
    benefit_percent                                  NUMERIC,
    benefit_start_date                               TIMESTAMP WITH TIME ZONE,
    benefit_end_date                                 TIMESTAMP WITH TIME ZONE,
    source_raw_benefit_type                          TEXT,
    source_raw_benefit_source_type                   TEXT,
    source_raw_benefit_status                        TEXT,
    source_raw_benefit_available                     TEXT,
    source_raw_benefit_provider                      TEXT,
    source_raw_employer                              TEXT,
    source_system_identifier                         TEXT,
    source_system_key_value                          TEXT,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_learner_third_party_benefit PRIMARY KEY (tenant_identifier, person_identifier, sequence_number)
);
COMMENT ON TABLE finances.learner_third_party_benefit IS 'A table that stores learner-associated third-party education benefit, sponsorship, tuition reimbursement, employer reimbursement, voucher, or outside funding-support facts. This table captures benefit eligibility or sponsorship context without becoming the authoritative financial-aid award, billing, payment, or ledger transaction table.';
COMMENT ON COLUMN finances.learner_third_party_benefit.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN finances.learner_third_party_benefit.person_identifier IS 'Tenant-scoped person/learner identifier to whom the benefit belongs.';
COMMENT ON COLUMN finances.learner_third_party_benefit.sequence_number IS 'Sequence number for multiple benefit rows for the learner.';
COMMENT ON COLUMN finances.learner_third_party_benefit.benefit_type_identifier IS 'Reference-code value identifying the type of third-party benefit.';
COMMENT ON COLUMN finances.learner_third_party_benefit.benefit_source_type_identifier IS 'Reference-code value identifying the type of benefit source or provider.';
COMMENT ON COLUMN finances.learner_third_party_benefit.benefit_status_identifier IS 'Reference-code value identifying the current known benefit status.';
COMMENT ON COLUMN finances.learner_third_party_benefit.benefit_available_indicator IS 'Indicates whether the source records a benefit or reimbursement as available.';
COMMENT ON COLUMN finances.learner_third_party_benefit.benefit_provider_name IS 'Name of the organization or party providing the benefit, reimbursement, or sponsorship.';
COMMENT ON COLUMN finances.learner_third_party_benefit.employer_name IS 'Employer name associated with the benefit when the benefit is employer-related.';
COMMENT ON COLUMN finances.learner_third_party_benefit.related_employment_sequence_number IS 'Optional sequence number linking the benefit to a related learner employment row.';
COMMENT ON COLUMN finances.learner_third_party_benefit.benefit_amount IS 'Benefit amount recorded by the source, where available; not an authoritative financial balance.';
COMMENT ON COLUMN finances.learner_third_party_benefit.benefit_percent IS 'Benefit percentage recorded by the source, where available.';
COMMENT ON COLUMN finances.learner_third_party_benefit.benefit_start_date IS 'Date and time the benefit started or became effective, where known.';
COMMENT ON COLUMN finances.learner_third_party_benefit.benefit_end_date IS 'Date and time the benefit ended or expired, where known.';
COMMENT ON COLUMN finances.learner_third_party_benefit.source_raw_benefit_type IS 'Source-system benefit type value preserved when canonical mapping is lossy.';
COMMENT ON COLUMN finances.learner_third_party_benefit.source_raw_benefit_source_type IS 'Source-system benefit source type value preserved when canonical mapping is lossy.';
COMMENT ON COLUMN finances.learner_third_party_benefit.source_raw_benefit_status IS 'Source-system benefit status value preserved when canonical mapping is lossy.';
COMMENT ON COLUMN finances.learner_third_party_benefit.source_raw_benefit_available IS 'Source-system benefit availability or reimbursement value preserved as supplied.';
COMMENT ON COLUMN finances.learner_third_party_benefit.source_raw_benefit_provider IS 'Source-system benefit provider value preserved as supplied.';
COMMENT ON COLUMN finances.learner_third_party_benefit.source_raw_employer IS 'Source-system employer value preserved as supplied.';
COMMENT ON COLUMN finances.learner_third_party_benefit.source_system_identifier IS 'Source system from which the third-party benefit row originated or can be reconciled.';
COMMENT ON COLUMN finances.learner_third_party_benefit.source_system_key_value IS 'Source-system key value for the third-party benefit row.';
COMMENT ON COLUMN finances.learner_third_party_benefit.created_by IS 'Person identifier that created the record';
COMMENT ON COLUMN finances.learner_third_party_benefit.created_date IS 'Date and time record was created';
COMMENT ON COLUMN finances.learner_third_party_benefit.updated_by IS 'Person identifier that updated the record';
COMMENT ON COLUMN finances.learner_third_party_benefit.updated_date IS 'Date and time record was updated';
COMMENT ON COLUMN finances.learner_third_party_benefit.deleted_by IS 'Person identifier that deleted the record';
COMMENT ON COLUMN finances.learner_third_party_benefit.deleted_date IS 'Date and time record was deleted';

