-- PersonFinances
-- A table containing the details of a person's finances that may contribute to funding learning
-- opportunities.
CREATE TABLE finances.person_finances (
    tenant_identifier                                UUID NOT NULL,
    person_identifier                                TEXT NOT NULL,
    person_finances_identifier                       TEXT NOT NULL,
    source_system_identifier                         TEXT,
    foreign_earned_income_exclusion                  NUMERIC,
    total_cash_savings_checking_assets               NUMERIC,
    net_worth_of_business_and_investment_farms       NUMERIC,
    net_worth_of_investments                         NUMERIC,
    filed_irs1040_form_indicator                     BOOLEAN,
    grants_scholarships_ameri_corps_income           NUMERIC,
    joint_tax_return_indicator                       BOOLEAN,
    earned_income_tax_credit_indicator               BOOLEAN,
    fafsa_consent_indicator                          BOOLEAN,
    annual_child_support_received                    NUMERIC,
    federal_housing_assistance_indicator             BOOLEAN,
    free_or_reduced_price_school_lunch_indicator     BOOLEAN,
    medicaid_indicator                               BOOLEAN,
    refundable_credit_for_coverage_under_qualified_health__7ba8de61 BOOLEAN,
    temporary_assistance_for_needy_families_indicator BOOLEAN,
    supplemental_nutrition_assistance_program_indicator BOOLEAN,
    special_supplemental_nutrition_program_for_wic_indicator BOOLEAN,
    irs_filing_status                                TEXT,
    supplemental_security_income_indicator           BOOLEAN,
    source_system_key_value                          TEXT,
    source_system_created_date                       DATE,
    source_system_updated_date                       DATE,
    source_system_deleted_date                       DATE,
    created_by                                       BIGINT NOT NULL,
    created_date                                     TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by                                       BIGINT,
    updated_date                                     TIMESTAMP WITH TIME ZONE,
    deleted_by                                       BIGINT,
    deleted_date                                     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT pk_person_finances PRIMARY KEY (tenant_identifier, person_finances_identifier)
);
COMMENT ON TABLE finances.person_finances IS 'A table containing the details of a person''s finances that may contribute to funding learning opportunities.';
COMMENT ON COLUMN finances.person_finances.tenant_identifier IS 'UUID identifying the tenant data-ownership and security boundary for this record.';
COMMENT ON COLUMN finances.person_finances.person_identifier IS 'A unique number or alphanumeric code assigned to a person';
COMMENT ON COLUMN finances.person_finances.person_finances_identifier IS 'Unique identifier for a person finances item';
COMMENT ON COLUMN finances.person_finances.source_system_identifier IS 'Unique identifier for the source system';
COMMENT ON COLUMN finances.person_finances.foreign_earned_income_exclusion IS 'Foreign Earned Income Exclusion in dollars as per the Internal Revenue Service (IRS)';
COMMENT ON COLUMN finances.person_finances.total_cash_savings_checking_assets IS 'Current total of cash, savings, and checking accounts in dollars, excluding student financial aid';
COMMENT ON COLUMN finances.person_finances.net_worth_of_business_and_investment_farms IS 'Current net worth of businesses, investment farms, and for-profit agricultural operations in dollars. Net worth is the value of the businesses or farms minus any debts owed against them.';
COMMENT ON COLUMN finances.person_finances.net_worth_of_investments IS 'Current net worth of investments in dollars, including real estate, but excluding the home the student lives in. Net worth is the value of the investments minus any debts owed against them.';
COMMENT ON COLUMN finances.person_finances.filed_irs1040_form_indicator IS 'Indicates whether the individual did or will file IRS Form 1040 or 1040-NR for the prior year';
COMMENT ON COLUMN finances.person_finances.grants_scholarships_ameri_corps_income IS 'Amount of College Grants, Scholarships, or AmeriCorps Benefits Reported as Income to the IRS';
COMMENT ON COLUMN finances.person_finances.joint_tax_return_indicator IS 'Indicates whether the learner/parent did or will file last year''s tax return jointly with their current spouse';
COMMENT ON COLUMN finances.person_finances.earned_income_tax_credit_indicator IS 'Indicates whether the student''s parent received the Earned Income Tax Credit (EITC) on last year''s tax return';
COMMENT ON COLUMN finances.person_finances.fafsa_consent_indicator IS 'Indicates whether or not the person gives consent to the FAFSA application taking their data directly from the IRS. If all persons contributing to the application do not give consent, then the application will automatically be denied.';
COMMENT ON COLUMN finances.person_finances.annual_child_support_received IS 'Indicates the total amount received in dollars in child support for the last complete calendar year';
COMMENT ON COLUMN finances.person_finances.federal_housing_assistance_indicator IS 'Indicates whether, at any time last year or this year, the learner/contributor or anyone in the family received benefits from federal housing assistance programs';
COMMENT ON COLUMN finances.person_finances.free_or_reduced_price_school_lunch_indicator IS 'Indicates whether, at any time last year or this year, did the learner/contributor or anyone in the family receive benefits from the Free or Reduced Price School Lunch federal program';
COMMENT ON COLUMN finances.person_finances.medicaid_indicator IS 'Indicates whether, at any time last year or this year, the learner/contributor or anyone in the family received benefits from Medicaid';
COMMENT ON COLUMN finances.person_finances.refundable_credit_for_coverage_under_qualified_health__7ba8de61 IS 'Indicates whether, at any time last year or this year, the learner/contributor or anyone in the family received benefits from the Refundable Credit for Coverage Under a Qualified Health Plan (QHP) federal program';
COMMENT ON COLUMN finances.person_finances.temporary_assistance_for_needy_families_indicator IS 'Indicates whether, at any time last year or this year, the learner/contributor or anyone in the family received benefits from the Temporary Assistance for Needy Families (TANF) federal program';
COMMENT ON COLUMN finances.person_finances.supplemental_nutrition_assistance_program_indicator IS 'Indicates whether, at any time last year or this year, the learner/contributor or anyone in the family received benefits from the Supplemental Nutrition Assistance Program (SNAP)';
COMMENT ON COLUMN finances.person_finances.special_supplemental_nutrition_program_for_wic_indicator IS 'Indicates whether, at any time last year or this year, the learner/contributor or anyone in the family received benefits from the Special Supplemental Nutrition Program for Women, Infants, and Children (WIC) federal program';
